"""Release-bank residency and interleaved flow-epoch online replay.

Atomic installs, eviction of an unreferenced previous bank, pinning by open
epochs (including classified ones), direction fixing, idle/segment/limit/close
commitment and the final residency snapshot all live here.
"""
from online_matching.match_p4 import BankMatcher

PADDING = 1514


class Epoch:
    """One open epoch of a flow; it pins the release current at open time."""

    __slots__ = ('flow', 'number', 'bank', 'matcher', 'stream', 'offset',
                 'consumed', 'last_ts', 'direction', 'classified')

    def __init__(self, flow, number, bank):
        self.flow = flow
        self.number = number
        self.bank = bank
        self.matcher = bank.matcher()
        self.offset = self.matcher.span
        self.stream = [PADDING] * self.offset
        self.consumed = 0
        self.last_ts = None
        self.direction = None
        self.classified = False

    def features(self):
        """First width encoded features, right padded when shorter."""
        width = self.bank.width
        values = self.stream[self.offset:self.offset + width]
        if len(values) < width:
            values = list(values) + [PADDING] * (width - len(values))
        return values


class SessionEngine:
    """Drives install/open/packet/close operations over the release banks."""

    def __init__(self, banks, capacity):
        self.banks = banks
        self.capacity = capacity
        self.current = None
        self.resident = set()
        self.pins = {}
        self.flows = {}
        self.installs = []
        self.decisions = []

    # ---- bank residency ------------------------------------------------
    def _usage(self, banks):
        used_range = 0
        used_exact = 0
        for release in banks:
            bank = self.banks[release]
            if bank.mode == 'range':
                used_range += bank.entries
            else:
                used_exact += bank.entries
        return used_range, used_exact

    def _snapshot(self):
        used_range, used_exact = self._usage(self.resident)
        return {'resident': sorted(self.resident),
                'used': {'range': used_range, 'exact': used_exact}}

    def install(self, release, at):
        bank = self.banks[release]
        limit = self.capacity['range' if bank.mode == 'range' else 'exact']
        if bank.entries > limit:
            status = 'oversize'
        else:
            previous = self.current
            evict = (previous is not None and previous != release and
                     not self.pins.get(previous, 0))
            prospective = set(self.resident)
            if evict:
                prospective.discard(previous)
            prospective.add(release)
            used_range, used_exact = self._usage(prospective)
            if used_range > self.capacity['range'] or used_exact > self.capacity['exact']:
                status = 'busy'
            else:
                status = 'ok'
                self.resident = prospective
                self.current = release
        snapshot = self._snapshot()
        self.installs.append({'at': at, 'id': release, 'status': status,
                              'resident': snapshot['resident'],
                              'used': snapshot['used']})

    # ---- epoch lifecycle -----------------------------------------------
    def open(self, flow, at):
        if self.current is None:
            raise ValueError('open without a current release')
        record = self.flows.get(flow)
        if record is not None and record[0] is not None:
            raise ValueError('open of an active flow')
        number = 0 if record is None else record[1]
        epoch = Epoch(flow, number, self.banks[self.current])
        self.flows[flow] = (epoch, number + 1)
        release = epoch.bank.id
        self.pins[release] = self.pins.get(release, 0) + 1

    def _commit(self, epoch, reason, at, seen, cluster, label, start):
        self.decisions.append({'flow': epoch.flow, 'epoch': epoch.number,
                               'release': epoch.bank.id, 'at': at, 'seen': seen,
                               'class': label, 'reason': reason,
                               'rule': cluster, 'start': start})
        epoch.classified = True

    def _classify_backup(self, epoch, reason, at, seen):
        label = epoch.bank.predict(epoch.features())
        self._commit(epoch, reason, at, seen, None, label, None)

    def packet(self, flow, timestamp, source, length, at):
        record = self.flows.get(flow)
        epoch = record[0] if record is not None else None
        if epoch is None:
            raise ValueError('packet for an inactive flow')
        if epoch.last_ts is not None and timestamp < epoch.last_ts:
            raise ValueError('decreasing timestamp in an epoch')
        if not epoch.classified:
            bank = epoch.bank
            if (epoch.consumed >= bank.width and epoch.last_ts is not None and
                    timestamp - epoch.last_ts > bank.idle_us):
                # idle backup wins before the arriving packet is consumed
                self._classify_backup(epoch, 'idle', at, epoch.consumed)
            else:
                self._consume(epoch, source, length)
                if not epoch.classified:
                    found = epoch.matcher.suffix_match(epoch.stream,
                                                       len(epoch.stream) - 1)
                    if found is not None:
                        rank, size = found
                        pattern = bank.patterns[rank]
                        self._commit(epoch, 'segment', at, epoch.consumed,
                                     pattern[2], pattern[3], epoch.consumed - size)
                    elif epoch.consumed > bank.packet_limit:
                        self._classify_backup(epoch, 'limit', at, epoch.consumed)
        epoch.last_ts = timestamp

    def _consume(self, epoch, source, length):
        if epoch.direction is None:
            epoch.direction = source
        if source == epoch.direction:
            epoch.stream.append(PADDING + length)
        else:
            epoch.stream.append(PADDING - length)
        epoch.consumed += 1

    def close(self, flow, at):
        record = self.flows.get(flow)
        epoch = record[0] if record is not None else None
        if epoch is None:
            raise ValueError('close of an inactive flow')
        if not epoch.classified:
            self._classify_backup(epoch, 'close', at, epoch.consumed)
        self.flows[flow] = (None, record[1])
        release = epoch.bank.id
        remaining = self.pins.get(release, 0) - 1
        if remaining:
            self.pins[release] = remaining
        else:
            self.pins.pop(release, None)
            if self.current != release:
                self.resident.discard(release)

    # ---- driver --------------------------------------------------------
    def run(self, blocks):
        at = 0
        for block in blocks:
            for event in block:
                kind = event[0]
                if kind == 'install':
                    self.install(event[1], at)
                elif kind == 'open':
                    self.open(event[1], at)
                elif kind == 'packet':
                    self.packet(event[1], event[2], event[3], event[4], at)
                else:
                    self.close(event[1], at)
                at += 1
        for record in self.flows.values():
            if record[0] is not None:
                raise ValueError('flow left open at the end of the request')
        final = {'current': self.current}
        final.update(self._snapshot())
        return self.installs, self.decisions, final
